let items=[],activeItem=null,timer=null,lastEvent=null,activeProductSection="all";
const upgradeById=new Map();

// V26: queste costanti devono essere inizializzate prima della prima render()
// chiamata da init(), altrimenti il TDZ di const interrompe il rendering dei pantaloni.
const compareSelected=new Set();
const MAX_COMPARE=4;
let compareOpen=false;
const $=s=>document.querySelector(s);
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
const fmt=v=>Number.isInteger(v)?String(v):String(Number(v.toFixed(3))).replace(".",",");
function imageUrl(i){return i.image||""}
function characterLevel(){
  const n=Number($("#level").value);
  return Number.isFinite(n)?Math.max(0,Math.floor(n)):0;
}
function selectedUpgrade(item){
  if(!item || item.upg!==1) return 0;
  const n=Number(upgradeById.get(String(item.id)) ?? 0);
  return Number.isFinite(n)?Math.min(5,Math.max(0,Math.floor(n))):0;
}
function perLevelInfo(item,k){
  const map=item.per_level;
  if(!map) return null;
  if(map[k]) return map[k];
  const aliases={
    str:"strength", mob:"flexibility", dex:"dexterity", cha:"charisma",
    sta:"endurance", tou:"tough", hea:"health", punch:"punch",
    ref:"reflex", dod:"dodge", fin:"finger_dexterity", hid:"hide",
    aim:"aim", pit:"pitfall", rid:"ride", ani:"animal", lea:"leadership",
    tra:"trade", rep:"repair", tac:"tactic", app:"appearance", swi:"swim",
    con:"build", sho:"shot", fir:"firearms", her:"herbalism",
    exp:"experience", con:"build", dmg:"damage"
  };
  const key=aliases[k]||k;
  return map[key]||null;
}
function nativeItemLevelBonus(level,value){
  level=Number(level)||0;
  value=Number(value)||0;
  if(!level||!value)return 0;
  if(value<1)return Math.round(Math.max(1,value*1000*level))/10000;
  return Math.round(Math.max(1,value*level/10));
}
function nativeRound(value,method){
  if(method==="round")return Math.round(value);
  if(method==="ceil")return Math.ceil(value);
  if(method==="floatceil")return Math.ceil(100*value)/100;
  if(method==="floor")return Math.floor(value);
  return value;
}
function nativeUpgradeValue(value,upgrade,nativeType){
  if(!upgrade||typeof value!=="number")return value;
  if(nativeType==="speed"){
    return value+Math.round((value*upgrade/10)*100)/100;
  }
  return value+nativeItemLevelBonus(upgrade,value);
}
function upgradeValue(v,upgrade,key){
  if(typeof v!=="number")return v;
  return nativeUpgradeValue(v,upgrade,key==="spd"?"speed":"");
}
function calcBonusValue(item,k,v,level,upgrade){
  const info=perLevelInfo(item,k);
  const isPercent=CONFIG.percentBonuses.has(k);
  let value=Math.abs(v);
  if(info){
    const method=info.roundingMethod||"ceil";
    const nativeType=info.nativeType||(k==="spd"?"speed":"");
    if(level>0){
      // BonusExtractor: prima applica il livello personaggio e il roundingMethod,
      // poi il miglioramento del pezzo, infine di nuovo il roundingMethod.
      value=nativeRound(value*level,method);
      value=nativeUpgradeValue(value,upgrade,nativeType);
      value=nativeRound(value,method);
      return isPercent?Math.round(value*100):value;
    }
    // Senza livello personaggio mostriamo il coefficiente "per Livello".
    value=nativeUpgradeValue(value,upgrade,nativeType);
    return isPercent?value*100:value;
  }
  value=nativeUpgradeValue(value,upgrade,k==="spd"?"speed":"");
  // Le percentuali fisse nel popup nativo vengono visualizzate come interi.
  return isPercent?Math.round(value*100):value;
}
function bonusHtml(k,v,level,upgrade,item){
  const value=calcBonusValue(item,k,v,level,upgrade);
  const suffix=perLevelInfo(item,k)&&level===0?` (${LANG.per_level})`:"";
  if(CONFIG.percentBonuses.has(k)) return `<p class="popup_txtgreen">+ ${fmt(value)}% ${CONFIG.bonusLabels[k]||k}${suffix}</p>`;
  const cls=(k==="str"||k==="mob"||k==="dex"||k==="cha")?"popup_attribute":"popup_skill";
  return `<p class="${cls}">+ ${fmt(value)} ${CONFIG.bonusLabels[k]||k}${suffix}</p>`;
}
function specialBonusHtml(k,v,item,upgrade){
  const value=calcBonusValue(item,k,v,characterLevel(),upgrade);
  const suffix=perLevelInfo(item,k)&&characterLevel()===0?` (${LANG.per_level})`:"";
  if(k.startsWith("fb")){
    const labels={fbdef:"Difesa (Bonus battaglia per il forte)",fboff:"Attacco (Bonus battaglia per il forte)",fbres:"Resistenza (Bonus battaglia per il forte)",fbdefs:"Difesa (Bonus settore battaglia per il forte)",fboffs:"Attacco (Bonus settore battaglia per il forte)",fbdmgs:"Danni (Bonus settore battaglia per il forte)"};
    return `<p class="popup_fb">+ ${fmt(value)} ${esc(labels[k]||k)}${suffix}</p>`;
  }
  if(k.startsWith("lbr_")){
    const found=(item._job_bonus_desc||[]).find(x=>`lbr_${x[0]}`===k);
    const label=found?String(found[1]).replace(/^\+\s*[-+\d.,]+\s*/,''):k;
    return `<p class="popup_txtgreen">+ ${fmt(value)} ${esc(label)}${suffix}</p>`;
  }
  if(k==="labor_pts") return `<p class="popup_txtgreen">+ ${fmt(value)} Punti lavoro${suffix}</p>`;
  if(k==="pra") return `<p class="popup_txtgreen">+ ${fmt(value)} Pregare${suffix}</p>`;
  if(k==="spd") return `<p class="popup_txtgreen">+ ${fmt(value)}% Velocità${suffix}</p>`;
  if(k==="health_bonus") return `<p class="popup_txtgreen">+ ${fmt(value)} Punti vita${suffix}</p>`;
  if(k==="revival") return `<p class="popup_txtgreen">Ripresa immediata dopo KO</p>`;
  if(k==="dmg") return `<p class="popup_dmg">+ ${fmt(value)} ${LANG.damages}${suffix}</p>`;
  return null;
}
const CRAFT_PROFESSION_NAMES={1:"Cuoco",2:"Medico Ciarlatano",3:"Fabbro",4:"Sellaio"};
function popupTypeLabel(item){
  if(String(item?.type||"")==="recipe") return "Ricette";
  return getItalianCategoryName(item);
}
function formatBlocktime(seconds){
  const s=Number(seconds)||0;
  if(!s)return "";
  const days=s/86400;
  if(Number.isInteger(days)) return `${days} ${days===1?"giorno":"giorni"}`;
  const hours=s/3600;
  if(Number.isInteger(hours)) return `${hours} ${hours===1?"ora":"ore"}`;
  return `${s} secondi`;
}
function productionBlocktime(item){
  if(String(item?.type||"")==="recipe") return Number(item.blocktime)||0;
  const recipe=items.find(r=>String(r?.type||"")==="recipe" && String(r.craftitem)===String(item?.id) && Number(r.blocktime)>0);
  return recipe?Number(recipe.blocktime)||0:0;
}
function createPopup(item){
  const a={...item}, level=characterLevel(), upgrade=selectedUpgrade(item), upgraded=upgrade>0;
  let s=`<div class="popup_image">`;
  if(upgraded)s+=`<div class="item_level_popup"><span>${upgrade}</span></div>`;
  s+=`<img src="${imageUrl(a)}" alt=""></div><div class="popup_divider"></div>`;
  const eventInfo=a.set&&EVENT_INFO_BY_SET[a.set]?EVENT_INFO_BY_SET[a.set]:null;s+=`<p class="popup_name">${esc(a.name)}</p>`;if(eventInfo)s+=`<p class="popup_event_line"><img src="${eventInfo.icon}" alt="">${esc(eventInfo.text)} ${esc(eventInfo.year)}</p>`;s+=`<p class="popup_type">${esc(popupTypeLabel(a))}</p>`;
  if(typeof a.description==="string"&&a.description.trim())s+=`<p class="popup_item_description">${esc(a.description)}</p>`;
  const blocktime=productionBlocktime(a);
  if(blocktime>0)s+=`<p class="popup_blocktime">Tempo di attesa: ${esc(formatBlocktime(blocktime))}</p>`;
  s+="<br/>";
  if(a.dmg_min!=null&&a.dmg_max!=null){const mn=upgradeValue(a.dmg_min,upgrade),mx=upgradeValue(a.dmg_max,upgrade);s+=`<p class="popup_dmg">${fmt(mn)}-${fmt(mx)} ${LANG.damages}</p>`;}
  if(Array.isArray(a.text)){for(const x of a.text)s+=`<p class="popup_text">${esc(x)}</p>`;s+="<br/>";}
  const handled=new Set(["name","type","cdn_cat","cdn_img","lvl","id","bp","sp","upg","auc","sex","text","textjob","bonus","dmg_min","dmg_max","hspd","set","craft","jobs","kshbn","bonus_desc","_job_bonus_desc","set_name"]);
  const order=["str","mob","dex","cha","con","punch","tou","sta","hea","rid","ref","dod","hid","swi","aim","sho","pit","fin","rep","lea","tac","tra","ani","app","fir","her","xp","money","luck","regen","drop","spd","pra","labor_pts","dmg","fbdef","fboff","fbres","fbdefs","fboffs","fbdmgs"];
  const keys=[...order,...Object.keys(item).filter(k=>!order.includes(k))];
  for(const k of keys){const v=item[k];if(handled.has(k)||typeof v!=="number"||(v===0&&k!=="pra"))continue;if(!Object.prototype.hasOwnProperty.call(CONFIG.bonusLabels,k)&&!k.startsWith("lbr_")&&!k.startsWith("fb"))continue;let h=null;if(k.startsWith("fb")||k.startsWith("lbr_")||["labor_pts","pra","health_bonus","revival","dmg"].includes(k) || (k==="spd" && !perLevelInfo(item,k)))h=specialBonusHtml(k,v,item,upgrade);else h=bonusHtml(k,v,level,upgrade,item);if(h)s+=h;}
  if(Array.isArray(a.textjob)){for(const x of a.textjob)s+=`<p class="popup_txtgreen">${esc(x)}</p>`;s+="<br/>";}
  if(Array.isArray(a.bonus)){for(const x of a.bonus)s+=`<p class="popup_bonus">${esc(x)}</p>`;s+="<br/>";}
  if(Array.isArray(a.usebonus)&&a.usebonus.length){s+=`<div class="popup_effect"><span class="popup_effect_title">Effetto</span>`;for(const line of a.usebonus){if(typeof line==="string"&&line.trim())s+=`<div class="popup_effect_line">${esc(line.trim())}</div>`;}s+="</div>";}
  if(Array.isArray(a.jobs)){s+=`<div style="text-align:center"><table class="popup_job">`;for(const job of a.jobs)s+=`<tr><td><img src="${CONFIG.cdn}/images/jobs/${esc(job[1])}.png"></td><td>&nbsp;&nbsp;${esc(job[0])}</td></tr>`;s+="</table></div>";}
  s+=`<div class="popup_infos">`;
  const italianSet=getItalianSetName(a);
  if(italianSet)s+=`<p class="popup_set">${esc(italianSet)}</p><br/>`;
  if(a.sp){s+=`<div class="popup_prices"><span class="popup_price"><img class="price_icon" src="${BUY_ICON}">${fmt(a.bp)} $</span><span class="popup_price"><img class="price_icon" src="${SELL_ICON}">${fmt(a.sp)} $</span></div>`;}else s+=`<i>${LANG.unsalable}</i><br/><br/>`;
  if(a.lvl)s+=`${LANG.level} <b>${a.lvl}</b><br/>`;
  s+=a.auc===1&&!upgraded?`<span class="popup_txtgreen">${LANG.auction}</span><br/>`:`<span class="popup_txtred">${LANG.not_auction}</span><br/>`;
  s+=a.upg===0?`<span class="popup_txtred">${LANG.not_upgrade}</span><br/>`:`<span class="popup_txtgreen">${LANG.upgrade}</span><br/>`;
  const shownId=upgrade?String(a.id).slice(0,-1)+upgrade:a.id;s+=`<br/><p class="popup_id">[item=<b>${esc(shownId)}</b>]</p></div>`;return s;
}
function position(ev){
  const p=$("#popup_window");
  const w=innerWidth,h=innerHeight,r=p.getBoundingClientRect();
  const x=ev.clientX+r.width+20>w?ev.clientX-r.width-20+(ev.pageX-ev.clientX):ev.clientX+20+(ev.pageX-ev.clientX);
  const y=ev.clientY+r.height+20>h?h-r.height+(ev.pageY-ev.clientY):ev.clientY+20+(ev.pageY-ev.clientY);
  p.style.top=`${Math.max(0,y)}px`;p.style.left=`${Math.max(0,x)}px`;
}
function show(item,ev){
  clearTimeout(timer);activeItem=item;lastEvent=ev;
  timer=setTimeout(()=>{
    if(activeItem!==item)return;
    $("#popup_contents").innerHTML=createPopup(item);
    const p=$("#popup_window");p.style.display="block";p.setAttribute("aria-hidden","false");position(lastEvent||ev);
  },200);
}
function hide(){clearTimeout(timer);activeItem=null;$("#popup_window").style.display="none";$("#popup_window").setAttribute("aria-hidden","true")}
function isPerLevelBonus(item,key){return !!perLevelInfo(item,key)}
function score(item,weights){
  let total=0;
  const level=characterLevel();
  for(const [k,m] of Object.entries(weights)){
    if(k==="bool"||k==="dmglvl")continue;
    const v=item[k];
    if(typeof v!=="number")continue;
    total += calcBonusValue(item,k,v,level,selectedUpgrade(item)) * m;
  }
  return total;
}

// V24 — stesso motore di ordinamento usato negli altri pacchetti.
// I Prodotti usano chiavi compatte, perciò traduciamo i criteri della UI
// nelle chiavi native già calcolate da calcBonusValue().
const PRODUCT_SORT_FIELD={
  strength:"str", flexibility:"mob", dexterity:"dex", charisma:"cha",
  build:"con", punch:"punch", tough:"tou", endurance:"sta", health:"hea",
  ride:"rid", reflex:"ref", dodge:"dod", hide:"hid", swim:"swi",
  aim:"aim", shot:"sho", pitfall:"pit", finger_dexterity:"fin", repair:"rep",
  leadership:"lea", tactic:"tac", trade:"tra", animal:"ani", appearance:"app",
  experience:"xp", dollar:"money", luck:"luck", regen:"regen", drop:"drop",
  speed:"spd", labor_pts:"labor_pts", pray:"pra",
  fbdef:"fbdef", fboff:"fboff", fbres:"fbres",
  fbdefs:"fbdefs", fboffs:"fboffs", fbdmgs:"fbdmgs"
};
const PRODUCT_COMBO_KEYS=new Set(Object.keys(PRODUCT_SORT_FIELD));
function isFullSaddleSection(section){return section==="saddles-set"||section==="saddles-noset";}
function productMetric(item,key){
  if(!key)return 0;
  if(key==="id")return Number(item.id)||0;
  if(key==="name")return item.name||"";
  if(key==="level")return Number(item.lvl)||0;
  if(key==="price")return Number(item.bp)||0;
  if(key==="upg_yes")return item.upg===1?1:0;
  if(key==="upg_no")return item.upg===1?0:1;
  if(key==="auc_yes")return item.auc===1?1:0;
  if(key==="auc_no")return item.auc===1?0:1;
  const f=PRODUCT_SORT_FIELD[key];
  if(!f)return 0;
  return compareValue(item,f)??0;
}
function compareProductMetric(a,b,key){
  const av=productMetric(a,key), bv=productMetric(b,key);
  if(key==="name"||typeof av==="string"||typeof bv==="string")
    return String(av??"").localeCompare(String(bv??""),"it",{sensitivity:"base"});
  return (Number(av)||0)-(Number(bv)||0);
}
function productSortComparator(a,b){
  const sort1=$("#sort")?.value||"id";
  const sort2=$("#sort2")?.value||"";
  const mode=$("#sort_mode")?.value||"priority";
  const order=$("#order")?.value||"asc";
  let cmp=0;
  if(sort2&&mode==="sum"&&PRODUCT_COMBO_KEYS.has(sort1)&&PRODUCT_COMBO_KEYS.has(sort2)){
    const av=(Number(productMetric(a,sort1))||0)+(Number(productMetric(a,sort2))||0);
    const bv=(Number(productMetric(b,sort1))||0)+(Number(productMetric(b,sort2))||0);
    cmp=av-bv;
    if(cmp===0)cmp=compareProductMetric(a,b,sort1);
    if(cmp===0)cmp=compareProductMetric(a,b,sort2);
  }else{
    cmp=compareProductMetric(a,b,sort1);
    if(cmp===0&&sort2)cmp=compareProductMetric(a,b,sort2);
  }
  if(cmp===0)cmp=(Number(a.id)||0)-(Number(b.id)||0);
  return order==="asc"?cmp:-cmp;
}
function sortProductItems(list,{selectedFirst=false}={}){
  const arr=[...list];
  arr.sort((a,b)=>{
    if(selectedFirst){
      const as=compareSelected.has(String(a.id)), bs=compareSelected.has(String(b.id));
      if(as!==bs)return as?-1:1;
    }
    return productSortComparator(a,b);
  });
  return arr;
}
function populateProductSecondarySort(){
  const primary=$("#sort"),secondary=$("#sort2");
  if(!primary||!secondary)return;
  // index.html contiene solo il placeholder di Ordina 2: cloniamo i criteri di Ordina 1.
  if(secondary.options.length<=1){
    for(const opt of primary.options){
      if(!opt.value)continue;
      const clone=opt.cloneNode(true);clone.selected=false;secondary.appendChild(clone);
    }
  }
}
function updateProductSortModeState(){
  const primary=$("#sort"),secondary=$("#sort2"),mode=$("#sort_mode");
  if(!primary||!secondary||!mode)return;
  if(secondary.value&&secondary.value===primary.value)secondary.value="";
  for(const opt of secondary.options)opt.disabled=!!opt.value&&opt.value===primary.value;
  const hasSecond=!!secondary.value;
  mode.disabled=!hasSecond;
  const sumOpt=[...mode.options].find(o=>o.value==="sum");
  const canSum=hasSecond&&PRODUCT_COMBO_KEYS.has(primary.value)&&PRODUCT_COMBO_KEYS.has(secondary.value);
  if(sumOpt)sumOpt.disabled=!canSum;
  if(mode.value==="sum"&&!canSum)mode.value="priority";
}
function updateProductSectionButtons(){
  const isSaddles=activeProductSection==="saddles"||activeProductSection.startsWith("saddles-");
  const isProduction=activeProductSection==="productions"||activeProductSection.startsWith("production-profession-");
  const isRecipes=activeProductSection==="recipes"||activeProductSection.startsWith("recipe-profession-");
  const isOther=activeProductSection==="other"||activeProductSection.startsWith("other-");
  document.querySelectorAll(".product-section-btn").forEach(b=>{
    let target=activeProductSection;
    if(isSaddles) target="saddles";
    if(isProduction) target="productions";
    if(isRecipes) target="recipes";
    if(isOther) target="other";
    b.classList.toggle("active",b.dataset.section===target);
  });
  const saddleSub=document.getElementById("saddle-set-filters");
  const productionSub=document.getElementById("production-profession-filters");
  const recipeSub=document.getElementById("recipe-profession-filters");
  const otherSub=document.getElementById("other-subcategory-filters");
  if(saddleSub) saddleSub.hidden=!isSaddles;
  if(productionSub) productionSub.hidden=!isProduction;
  if(recipeSub) recipeSub.hidden=!isRecipes;
  if(otherSub) otherSub.hidden=!isOther;
  document.querySelectorAll(".saddle-set-filter-btn").forEach(b=>b.classList.toggle("active",activeProductSection==="saddles-"+b.dataset.setfilter));
  document.querySelectorAll(".production-profession-filter-btn").forEach(b=>b.classList.toggle("active",activeProductSection==="production-profession-"+b.dataset.profession));
  document.querySelectorAll(".recipe-profession-filter-btn").forEach(b=>b.classList.toggle("active",activeProductSection==="recipe-profession-"+b.dataset.profession));
  document.querySelectorAll(".other-subcategory-filter-btn").forEach(b=>b.classList.toggle("active",activeProductSection==="other-"+b.dataset.other));
}
function init(){
  items=EMBEDDED_ITEMS.map(x=>({...x, set_name:getItalianSetName(x)}));
  $("#count").textContent=`${items.length} oggetti`;
  $("#search").addEventListener("input",render);
  document.querySelectorAll(".product-section-btn").forEach(btn=>{
    btn.addEventListener("click",()=>{
      hide();
      hideRequirements();
      const section=btn.dataset.section;
      // v17: i pulsanti sono selezioni, non toggle.
      // Un secondo click sulla sezione attiva lascia la stessa sezione visibile.
      if(activeProductSection!==section){compareSelected.clear();compareOpen=false;}
      activeProductSection=section;
      activeCollectionPackId=null;
      updateProductSectionButtons();
      render();
    });
  });
  document.querySelectorAll(".saddle-set-filter-btn").forEach(btn=>{
    btn.addEventListener("click",()=>{
      hide();
      hideRequirements();
      const section="saddles-"+btn.dataset.setfilter;
      if(activeProductSection!==section){compareSelected.clear();compareOpen=false;}
      activeProductSection=section;
      updateProductSectionButtons();
      render();
    });
  });
  document.querySelectorAll(".production-profession-filter-btn").forEach(btn=>{
    btn.addEventListener("click",()=>{
      hide();
      hideRequirements();
      const section="production-profession-"+btn.dataset.profession;
      if(activeProductSection!==section){compareSelected.clear();compareOpen=false;}
      activeProductSection=section;
      updateProductSectionButtons();
      render();
    });
  });
  document.querySelectorAll(".recipe-profession-filter-btn").forEach(btn=>{
    btn.addEventListener("click",()=>{
      hide();
      hideRequirements();
      const section="recipe-profession-"+btn.dataset.profession;
      if(activeProductSection!==section){compareSelected.clear();compareOpen=false;}
      activeProductSection=section;
      activeCollectionPackId=null;
      updateProductSectionButtons();
      render();
    });
  });
  document.querySelectorAll(".other-subcategory-filter-btn").forEach(btn=>{
    btn.addEventListener("click",()=>{
      hide();
      hideRequirements();
      const section="other-"+btn.dataset.other;
      if(activeProductSection!==section){compareSelected.clear();compareOpen=false;}
      activeProductSection=section;
      activeCollectionPackId=null;
      updateProductSectionButtons();
      render();
    });
  });
  populateProductSecondarySort();
  updateProductSortModeState();
  $("#sort").addEventListener("change",()=>{updateProductSortModeState();render();});
  $("#sort2").addEventListener("change",()=>{updateProductSortModeState();render();});
  $("#sort_mode").addEventListener("change",render);
  $("#order").addEventListener("change",render);
  $("#level").addEventListener("input",()=>{
    render();
    if(activeItem&&$("#popup_window").style.display==="block")$("#popup_contents").innerHTML=createPopup(activeItem);
  });
  render();
}
init();

/* =========================
   V25 UI: inline upgrade + multi-select compare
   ========================= */
function compareValue(item,key){
  const v=item[key];
  if(typeof v!=="number" || (v===0 && key!=="pra")) return null;
  return calcBonusValue(item,key,v,characterLevel(),selectedUpgrade(item));
}
function compareLabel(item,key){
  if(CONFIG.bonusLabels[key]) return CONFIG.bonusLabels[key];
  if(key.startsWith("fb")) return ({fbdef:"Difesa (Bonus battaglia)",fboff:"Attacco (Bonus battaglia)",fbres:"Resistenza (Bonus battaglia)",fbdefs:"Difesa (Bonus settore battaglia)",fboffs:"Attacco (Bonus settore battaglia)",fbdmgs:"Danni (Bonus settore battaglia)"})[key]||key;
  if(key.startsWith("lbr_")){
    const found=(item._job_bonus_desc||[]).find(x=>`lbr_${x[0]}`===key);
    return found?String(found[1]).replace(/^\+\s*[-+\d.,]+\s*/,""):key;
  }
  return null;
}
function compareFormat(item,key,value){
  if(value==null)return "—";
  const pct=CONFIG.percentBonuses.has(key);
  const sign=value>0?"+ ":"";
  return sign+fmt(value)+(pct?"%":"");
}
function compareKeys(a,b){
  const order=["spd","xp","money","luck","regen","drop","str","mob","dex","cha","con","punch","tou","sta","hea","rid","ref","dod","hid","swi","aim","sho","pit","fin","rep","lea","tac","tra","ani","app","labor_pts","pra","health_bonus","revival","dmg","fbdef","fboff","fbres","fbdefs","fboffs","fbdmgs"];
  const all=[...order,...Object.keys(a||{}),...Object.keys(b||{})];
  return [...new Set(all)].filter(k=>compareLabel(a,k)||compareLabel(b,k)).filter(k=>compareValue(a,k)!==null||compareValue(b,k)!==null);
}
function renderCompare(){
  const panel=$("#compare_panel");
  if(!panel)return;
  if(!isFullSaddleSection(activeProductSection)||!compareOpen){panel.hidden=true;panel.innerHTML="";return;}
  const chosen=sortProductItems(items.filter(i=>compareSelected.has(String(i.id)) &&
    (activeProductSection==="saddles-set"?isSaddleSet(i):isSaddleNoSet(i)))).slice(0,MAX_COMPARE);
  if(chosen.length<1){panel.hidden=true;panel.innerHTML="";return;}
  panel.hidden=false;
  const cols=chosen.length;
  let html=`<div class="compare_title">CONFRONTO · ${chosen.length} sell${chosen.length===1?"a":"e"}</div>`;
  html+=`<div class="compare_multi_head" style="grid-template-columns:repeat(${cols},minmax(0,1fr))">`;
  for(const x of chosen){
    const up=selectedUpgrade(x);
    html+=`<div class="compare_card"><img src="${imageUrl(x)}" alt="${esc(x.name)}"><div class="compare_name">${esc(x.name)}</div><div class="compare_lvl">${up?`<span class="icon_level"></span>${up}`:"Base"}</div></div>`;
  }
  html+=`</div>`;
  const keySet=new Set();
  for(const x of chosen)for(const k of Object.keys(x))if(compareLabel(x,k)&&compareValue(x,k)!==null)keySet.add(k);
  const order=["spd","xp","money","luck","regen","drop","str","mob","dex","cha","con","punch","tou","sta","hea","rid","ref","dod","hid","swi","aim","sho","pit","fin","rep","lea","tac","tra","ani","app","labor_pts","pra","health_bonus","revival","dmg","fbdef","fboff","fbres","fbdefs","fboffs","fbdmgs"];
  const keys=[...order,...keySet].filter((k,i,a)=>a.indexOf(k)===i&&keySet.has(k));
  html+=`<table class="compare_table compare_multi"><tbody>`;
  for(const k of keys){
    const vals=chosen.map(x=>compareValue(x,k));
    const nums=vals.filter(v=>v!=null&&Number.isFinite(Number(v))).map(Number);
    const max=nums.length?Math.max(...nums):null,min=nums.length?Math.min(...nums):null;
    html+=`<tr>`;
    vals.forEach((v,idx)=>{
      const num=v==null?null:Number(v);
      let cls="equal";
      if(num!=null&&Number.isFinite(num)&&max!==null&&min!==null&&max!==min)cls=num===max?"better":num===min?"worse":"equal";
      html+=`<td class="val ${cls}">${compareFormat(chosen[idx],k,v)}</td>`;
    });
    html+=`</tr>`;
    html+=`<tr class="compare_label_row"><td colspan="${cols}">${esc(compareLabel(chosen.find(x=>compareValue(x,k)!==null)||chosen[0],k)||k)}</td></tr>`;
  }
  html+=`</tbody></table>`;
  const lvlHint=characterLevel()?"":" · Senza livello: i bonus per livello sono confrontati sul coefficiente base.";
  html+=`<div class="compare_hint">Verde = valore migliore · Rosso = valore peggiore · Base o migliorata: usa + / − direttamente sulla sella selezionata.${lvlHint}</div>`;
  panel.innerHTML=html;
}

function updateCompareBar(){
  const n=compareSelected.size;
  const status=$("#compare_status");
  if(status)status.textContent=n===0?"Seleziona 1–4 selle per il confronto":`${n} sell${n===1?"a":"e"} selezionat${n===1?"a":"e"}`;
  const btn=$("#compare_btn");
  if(btn)btn.disabled=n<1;
}
function updateLevelBadge(el,item){
  const lvl=selectedUpgrade(item);
  const controls=el.querySelector(".upgrade_controls");
  if(controls){
    controls.dataset.lvl=String(lvl);
    const badge=controls.querySelector(".item_level");
    const value=controls.querySelector(".upgrade_level_value");
    if(badge){
      badge.innerHTML=`<span class="icon_level"></span>`;
    }
    if(value) value.textContent=String(lvl);
  }
  el.dataset.lvl=String(lvl);
}
function setUpgrade(item,level,el){
  level=Math.max(0,Math.min(5,Number(level)||0));
  upgradeById.set(String(item.id),level);
  updateLevelBadge(el,item);
  // Come negli altri pacchetti: un miglioramento può cambiare l'ordinamento.
  if(isFullSaddleSection(activeProductSection)){
    render();
  }else{
    renderCompare();
  }

  // Riagganciamo il popup al valore appena aggiornato.
  activeItem=item;
  const popup=$("#popup_window");
  $("#popup_contents").innerHTML=createPopup(item);
  popup.style.display="block";
  popup.setAttribute("aria-hidden","false");
  if(lastEvent)position(lastEvent);
}
function makeUpgradeButton(cls,title,item,el,delta){
  const b=document.createElement("span");
  b.className=cls;b.title=title; b.setAttribute("role","button"); b.tabIndex=0;
  // Passando sui +/- mostriamo sempre il popup dell'oggetto, già al livello corrente.
  b.addEventListener("mouseenter",e=>{
    e.stopPropagation();
    lastEvent=e;
    activeItem=item;
    $("#popup_contents").innerHTML=createPopup(item);
    const p=$("#popup_window");
    p.style.display="block";
    p.setAttribute("aria-hidden","false");
    position(e);
  });
  const act=e=>{
    e.preventDefault();
    e.stopPropagation();
    setUpgrade(item,selectedUpgrade(item)+delta,el);
  };
  b.addEventListener("mousedown",e=>e.stopPropagation());
  b.addEventListener("click",act);
  b.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" ")act(e)});
  return b;
}
function makeCompareCheck(item,el){
  const c=document.createElement("input");
  c.type="checkbox";c.className="compare_check";c.title="Seleziona per il confronto";
  c.checked=compareSelected.has(String(item.id));
  c.addEventListener("mousedown",e=>e.stopPropagation());
  c.addEventListener("click",e=>e.stopPropagation());
  c.addEventListener("change",e=>{
    const id=String(item.id);
    if(e.target.checked){
      if(compareSelected.size>=MAX_COMPARE){e.target.checked=false;return;}
      compareSelected.add(id);
    }else compareSelected.delete(id);
    // Le selle selezionate salgono immediatamente davanti nella griglia.
    render();
  });
  return c;
}
// Classificazione provvisoria Selle: yield da evento (anno nell'identificativo)
// e oggetti di set evento con lo schema *_YYYY_setN, anche quando short è generico.
function isEventSaddle(item){
  if(item.type==="recipe") return false;
  const short=String(item.short||"").toLowerCase();
  const set=String(item.set||"").toLowerCase();
  const yieldShort=/(?:^|_)yield(?:_|$)/.test(short);
  const hasEventYear=/20\d{2}/.test(short)||/20\d{2}/.test(set);
  const eventSet=/(?:^|_)set\d+(?:_|$)/.test(set) && /20\d{2}/.test(set);
  return (yieldShort&&hasEventYear)||eventSet;
}
