let activeCollectionPackId=null;
function isEventCurrency(item){return EVENT_CURRENCY_IDS.has(item.id);}
function isCollectionPack(item){return COLLECTION_PACK_IDS.has(item.id);}
function isAvatarPart(item){return AVATAR_PART_IDS.has(item.id);}
function isSaddle(item){
  if(EXCLUDE_FROM_SADDLES_IDS.has(item.id)) return false;
  return !isChest(item) && (
    FORCE_SADDLE_SET_IDS.has(item.id) ||
    FORCE_SADDLE_NOSET_IDS.has(item.id) ||
    isEventSaddle(item) ||
    (item.type==="yield" && BONUS_SADDLE_IDS.has(item.id))
  );
}
function isSaddleSet(item){
  return isSaddle(item) && (!!item.set || FORCE_SADDLE_SET_IDS.has(item.id));
}
function isSaddleNoSet(item){
  return isSaddle(item) && !isSaddleSet(item);
}
const EXTRA_MAPDROP_IDS = new Set([1828000,1829000,1830000,2000000,2003000,2006000,2009000]);
function isChest(i){
  if(i.type==="recipe" || !Array.isArray(i.usebonus)) return false;
  return i.usebonus.some(value=>typeof value==="string" && (
    value.trim()==="Qualcosa da scartare..." ||
    value.trim().toLowerCase().startsWith("contiene uno dei seguenti oggetti:")
  ));
}

function escAttr(s){
  return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
}
function isProductionSectionName(section){
  return section==="productions" || section.startsWith("production-profession-");
}
function isRecipeSectionName(section){
  return section==="recipes" || section.startsWith("recipe-profession-");
}
function isNoCompareSectionName(section){
  // V24: solo Selle SET / NO SET hanno livello, ordinamenti, upgrade e confronto.
  // Tutte le altre sezioni conservano esclusivamente il campo Cerca.
  return !isFullSaddleSection(section);
}
function hideRequirements(){
  const p=document.getElementById("requirements_panel");
  if(p){p.hidden=true;p.innerHTML="";}
}
function getCraftEntry(productId){
  const arr=CRAFT_REQUIREMENTS_BY_PRODUCT[String(productId)]||[];
  return arr.length?arr[0]:null;
}
function itemNameById(id){
  const x=items.find(i=>String(i.id)===String(id));
  if(x) return x.name||("Oggetto "+id);
  for(const arr of Object.values(CRAFT_REQUIREMENTS_BY_PRODUCT)){
    for(const rec of arr||[]) for(const r of rec.resources||[]) if(String(r.id)===String(id)) return r.name||("Oggetto "+id);
  }
  return "Oggetto "+id;
}
function itemImageById(id){
  const x=items.find(i=>String(i.id)===String(id));
  if(x) return x.image||"";
  for(const arr of Object.values(CRAFT_REQUIREMENTS_BY_PRODUCT)){
    for(const rec of arr||[]) for(const r of rec.resources||[]) if(String(r.id)===String(id)) return r.image||"";
  }
  return "";
}
function collectBaseMaterials(productId,qty,out,path){
  out=out||{}; path=path||new Set();
  const id=String(productId), amount=Math.max(0,Number(qty)||0);
  if(path.has(id)){ out[id]=(out[id]||0)+amount; return out; }
  const rec=getCraftEntry(id);
  if(!rec || !(rec.resources||[]).length){ out[id]=(out[id]||0)+amount; return out; }
  const next=new Set(path); next.add(id);
  for(const r of rec.resources||[]) collectBaseMaterials(r.id,amount*Number(r.count||0),out,next);
  return out;
}
function requirementTreeHtml(productId,qty,depth,path){
  const id=String(productId), amount=Math.max(0,Number(qty)||0), rec=getCraftEntry(id);
  path=path||new Set();
  if(!rec || !(rec.resources||[]).length) return "";
  if(path.has(id)) return `<div class="req_cycle">Ciclo rilevato: ${esc(itemNameById(id))}</div>`;
  const next=new Set(path); next.add(id);
  let html=`<div class="req_tree_level" data-depth="${depth||0}">`;
  for(const r of rec.resources||[]){
    const childQty=amount*Number(r.count||0);
    const childRec=getCraftEntry(r.id);
    html+=`<div class="req_tree_row ${childRec?"craftable":"base"}">`;
    if(r.image) html+=`<img src="${escAttr(r.image)}" alt="">`;
    html+=`<span class="req_tree_qty">×${childQty}</span><span class="req_tree_name">${esc(r.name||("Oggetto "+r.id))}</span>`;
    if(childRec){
      if(childRec.profession) html+=`<em>Produzione del ${esc(childRec.profession)}</em>`;
      html+=`<button type="button" class="req_inline_btn" data-product-id="${r.id}" title="Cosa serve per ${escAttr(r.name||("Oggetto "+r.id))}">?</button>`;
    }
    html+=`</div>`;
    if(childRec){
      html+=`<div class="req_tree_branch"><div class="req_arrow">↓</div>${requirementTreeHtml(r.id,childQty,(depth||0)+1,next)}</div>`;
    }
  }
  html+=`</div>`;
  return html;
}
function baseSummaryHtml(productId,qty){
  const totals=collectBaseMaterials(productId,qty,{},new Set());
  const rows=Object.entries(totals).sort((a,b)=>itemNameById(a[0]).localeCompare(itemNameById(b[0]),"it"));
  if(!rows.length) return "";
  let html=`<div class="req_base_summary"><div class="req_base_title">Totale prodotti base</div><div class="req_base_grid">`;
  for(const [id,count] of rows){
    const img=itemImageById(id);
    html+=`<div class="req_base_item">${img?`<img src="${escAttr(img)}" alt="">`:""}<b>×${count}</b><span>${esc(itemNameById(id))}</span></div>`;
  }
  return html+`</div></div>`;
}
function directRequirementsHtml(productId,qty){
  const rec=getCraftEntry(productId);
  if(!rec || !(rec.resources||[]).length) return "";
  let html=`<div class="req_direct_title">Cosa serve</div><div class="req_direct_grid">`;
  for(const r of rec.resources||[]){
    const amount=Math.max(0,Number(qty)||0)*Number(r.count||0);
    const craftable=!!getCraftEntry(r.id);
    html+=`<div class="req_direct_item ${craftable?"craftable":""}">`;
    if(r.image) html+=`<img src="${escAttr(r.image)}" alt="">`;
    html+=`<b>×${amount}</b><span>${esc(r.name||("Oggetto "+r.id))}</span>`;
    if(craftable){
      const childRec=getCraftEntry(r.id);
      html+=`<em>${childRec&&childRec.profession?`Produzione del ${esc(childRec.profession)}`:"Produzione"}</em>`;
    }
    html+=`</div>`;
  }
  return html+`</div>`;
}
function renderRequirementsPanel(item,qty){
  const panel=document.getElementById("requirements_panel"); if(!panel)return;
  qty=Math.max(1,Math.floor(Number(qty)||1));
  const entries=CRAFT_REQUIREMENTS_BY_PRODUCT[String(item.id)]||[];

  let html=`<div class="requirements_header"><strong>Cosa serve</strong><span>${esc(item.name)}</span><button type="button" class="requirements_close" title="Chiudi">×</button></div>`;
  html+=`<div class="requirements_quantity"><label>${esc(item.name)}: quanti ne vuoi produrre? <input id="requirements_qty" type="number" min="1" step="1" value="${qty}"></label><button type="button" id="requirements_update" class="requirements_update_btn">Aggiorna</button></div>`;

  if(!entries.length){
    html+=`<div class="requirements_empty">Per questo prodotto non abbiamo ancora i materiali della ricetta nei dati disponibili.</div>`;
  }else{
    const rec=entries[0];
    html+=`<div class="requirements_recipe"><div class="requirements_recipe_head">${esc(rec.profession||"Professione")} · ${esc(rec.recipe_name||"Ricetta")}</div>`;
    html+=directRequirementsHtml(item.id,qty);
    html+=`</div>`;
    html+=baseSummaryHtml(item.id,qty).replace("Totale prodotti base","Cosa serve complessivamente");
  }

  panel.innerHTML=html;
  panel.hidden=false;

  const close=panel.querySelector(".requirements_close");
  if(close) close.addEventListener("click",hideRequirements);

  const input=panel.querySelector("#requirements_qty");
  const update=panel.querySelector("#requirements_update");
  const refresh=()=>renderRequirementsPanel(item,input?input.value:qty);

  if(update) update.addEventListener("click",refresh);
  if(input) input.addEventListener("keydown",e=>{
    if(e.key==="Enter"){ e.preventDefault(); refresh(); }
  });
}
function showRequirements(item,qty){
  const panel=document.getElementById("requirements_panel"); if(!panel)return;
  renderRequirementsPanel(item,qty||1);
  panel.scrollIntoView({behavior:"smooth",block:"nearest"});
}
function makeRequirementsButton(item){
  const b=document.createElement("button"); b.type="button"; b.className="requirements_item_btn"; b.title="Cosa serve"; b.setAttribute("aria-label","Cosa serve"); b.textContent="?";
  b.addEventListener("mouseenter",e=>e.stopPropagation()); b.addEventListener("mousemove",e=>e.stopPropagation());
  b.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();showRequirements(item,1);}); return b;
}

function collectionCardsFor(item){
  return COLLECTION_CARDS_BY_PACK[String(item.id)]||[];
}
function makeCollectionArrow(item){
  const b=document.createElement("button");
  b.type="button";
  b.className="collection_expand_btn"+(String(activeCollectionPackId)===String(item.id)?" active":"");
  b.title="Scopri le 5 carte da collezione";
  b.setAttribute("aria-label","Scopri le 5 carte da collezione");
  b.textContent="?";
  b.addEventListener("mouseenter",e=>e.stopPropagation());
  b.addEventListener("mousemove",e=>e.stopPropagation());
  b.addEventListener("mousedown",e=>e.stopPropagation());
  b.addEventListener("click",e=>{
    e.preventDefault();
    e.stopPropagation();
    hide();
    activeCollectionPackId=String(activeCollectionPackId)===String(item.id)?null:String(item.id);
    render();
    if(activeCollectionPackId){
      const detail=document.querySelector(`.collection_cards_detail[data-pack-id="${item.id}"]`);
      if(detail) detail.scrollIntoView({behavior:"smooth",block:"nearest"});
    }
  });
  return b;
}
function makeCollectionDetail(item){
  const cards=collectionCardsFor(item);
  const box=document.createElement("div");
  box.className="collection_cards_detail";
  box.dataset.packId=String(item.id);
  let html=`<div class="collection_cards_head"><strong>Carte contenute in:</strong> <span>${esc(item.name)}</span><small>${cards.length} carte</small></div>`;
  html+=`<div class="collection_cards_grid">`;
  for(const card of cards){
    html+=`<div class="collection_child_card" title="${escAttr(card.name)}">`;
    if(card.image) html+=`<img src="${escAttr(card.image)}" alt="${escAttr(card.name)}">`;
    html+=`<span>${esc(card.name)}</span></div>`;
  }
  html+=`</div>`;
  box.innerHTML=html;
  return box;
}

function render(){
  const q=$("#search").value.trim().toLowerCase();
  const section=activeProductSection;
  const productionMode=isProductionSectionName(section);
  const fullSaddleMode=isFullSaddleSection(section);
  const simpleMode=!fullSaddleMode;
  const compareBar=document.getElementById("compare_bar");
  const comparePanel=document.getElementById("compare_panel");
  const levelBox=document.getElementById("input_level");
  const upgradeBox=document.getElementById("input_upgrade");
  const sortBox=document.getElementById("sort_items");
  const toolbar=document.querySelector(".toolbar");
  if(compareBar)compareBar.hidden=simpleMode;
  if(levelBox)levelBox.hidden=simpleMode;
  if(upgradeBox)upgradeBox.hidden=simpleMode;
  if(sortBox)sortBox.hidden=simpleMode;
  if(toolbar){
    toolbar.classList.toggle("production_mode",simpleMode);
    toolbar.classList.toggle("simple_mode",simpleMode);
  }
  if(simpleMode&&comparePanel){comparePanel.hidden=true;comparePanel.innerHTML="";}
  if(!productionMode)hideRequirements();
  const hasUseAction=i=>String(i.action||"").trim().startsWith("ItemUse.use");
  const isMapdropItem=i=>EXTRA_MAPDROP_IDS.has(i.id)||(i.sections||[]).includes("mapdrop");
  const isExistingQuest=i=>(i.sections||[]).includes("quest");
  const isProductionItem=i=>(CRAFT_PROFESSIONS_BY_ITEM[String(i.id)]||[]).length>0;
  const isBaseUncatalogued=i=>i.type!=="recipe"&&!isMapdropItem(i)&&!isExistingQuest(i)&&!isProductionItem(i)&&!isSaddle(i)&&!isChest(i);
  const isMovedToQuest=i=>isBaseUncatalogued(i)&&!hasUseAction(i)&&!FORCE_OTHER_IDS.has(i.id);
  const matchesSection=i=>{
    if(section==="all")return i.type!=="recipe";
    if(section==="saddles")return false;
    if(section==="saddles-set")return isSaddleSet(i);
    if(section==="saddles-noset")return isSaddleNoSet(i);
    if(section==="chests")return isChest(i);
    if(section==="mapdrop")return i.type!=="recipe"&&isMapdropItem(i);
    if(section==="quest")return i.type!=="recipe"&&!FORCE_OTHER_IDS.has(i.id)&&(FORCE_QUEST_ONLY_IDS.has(i.id)||isExistingQuest(i)||isMovedToQuest(i));
    if(section==="productions")return false;
    if(section.startsWith("production-profession-")){
      const pid=Number(section.slice("production-profession-".length));
      return i.type!=="recipe"&&(CRAFT_PROFESSIONS_BY_ITEM[String(i.id)]||[]).includes(pid);
    }
    if(section==="recipes")return false;
    if(section.startsWith("recipe-profession-")){
      const pid=Number(section.slice("recipe-profession-".length));
      return i.type==="recipe"&&(CRAFT_RECIPE_PROFESSIONS_BY_ITEM[String(i.id)]||[]).includes(pid);
    }
    if(section==="other-events")return i.type!=="recipe"&&isEventCurrency(i);
    if(section==="other-cards")return i.type!=="recipe"&&isCollectionPack(i);
    if(section==="other-avatar")return i.type!=="recipe"&&isAvatarPart(i);
    if(section==="other")return i.type!=="recipe"&&!isEventCurrency(i)&&!isCollectionPack(i)&&!isAvatarPart(i)&&(FORCE_OTHER_IDS.has(i.id)||(isBaseUncatalogued(i)&&hasUseAction(i)));
    return i.type!=="recipe"&&(i.sections||[]).includes(section);
  };
  const matchesSearch=i=>{
    if(!q)return true;
    if(JSON.stringify(i).toLowerCase().includes(q))return true;
    if(section==="other-cards")return collectionCardsFor(i).some(card=>JSON.stringify(card).toLowerCase().includes(q));
    return false;
  };
  let list=items.filter(i=>matchesSection(i)&&matchesSearch(i));
  const showingRecipes=section==="recipes"||section.startsWith("recipe-profession-");
  const totalForMode=showingRecipes?items.filter(i=>i.type==="recipe").length:items.filter(i=>i.type!=="recipe").length;
  if(section==="other-events"){
    $("#count").textContent=`${list.length} / ${EVENT_CURRENCY_IDS.size} valute evento`;
  }else if(section==="other-cards"){
    const visibleCards=list.reduce((sum,i)=>sum+collectionCardsFor(i).length,0);
    $("#count").textContent=`${list.length} / ${COLLECTION_PACK_IDS.size} pacchetti · ${visibleCards} carte`;
  }else if(section==="other-avatar"){
    $("#count").textContent=`${list.length} / ${AVATAR_PART_IDS.size} parti avatar`;
  }else{
    $("#count").textContent=`${list.length} / ${totalForMode} ${showingRecipes?"ricette":"prodotti"}`;
  }
  if(fullSaddleMode)list=sortProductItems(list,{selectedFirst:true});
  const c=$("#items");c.innerHTML="";
  for(const item of list){
    const el=document.createElement("div");
    el.className="item_container"+(compareSelected.has(String(item.id))?" compare_selected":"");
    el.dataset.popup=JSON.stringify(item);el.dataset.lvl=String(selectedUpgrade(item));
    const img=new Image();img.src=imageUrl(item);img.alt=item.name;img.loading="lazy";
    img.onerror=()=>{img.style.display="none";el.insertAdjacentHTML("beforeend",`<div class="item_missing" title="Immagine non disponibile dal CDN"><div class="fallback_hat">🎩</div><span>${esc(item.name)}</span></div>`)};
    el.appendChild(img);
    if(fullSaddleMode&&item.upg===1){
      const controls=document.createElement("span");
      controls.className="upgrade_controls";controls.dataset.lvl=String(selectedUpgrade(item));
      const badge=document.createElement("span");badge.className="item_level";badge.innerHTML=`<span class="icon_level"></span>`;controls.appendChild(badge);
      controls.appendChild(makeUpgradeButton("upgrade","Migliora di 1 livello",item,el,1));
      const levelSpan=document.createElement("span");levelSpan.className="upgrade_level_value level";levelSpan.textContent=String(selectedUpgrade(item));controls.appendChild(levelSpan);
      controls.appendChild(makeUpgradeButton("downgrade","Riduci di 1 livello",item,el,-1));
      el.appendChild(controls);
    }
    if(productionMode)el.appendChild(makeRequirementsButton(item));
    else if(section==="other-cards")el.appendChild(makeCollectionArrow(item));
    else if(fullSaddleMode)el.appendChild(makeCompareCheck(item,el));
    el.addEventListener("mouseenter",e=>show(item,e));
    el.addEventListener("mousemove",e=>{lastEvent=e;if($("#popup_window").style.display==="block")position(e)});
    el.addEventListener("mouseleave",hide);
    c.appendChild(el);
    if(section==="other-cards"&&String(activeCollectionPackId)===String(item.id))c.appendChild(makeCollectionDetail(item));
  }
  updateCompareBar();renderCompare();
}

// V25 init: direct controls, no M0/M1... selectors.
(function wireV25(){
  const compareBtn=$("#compare_btn"),clearBtn=$("#compare_clear");
  if(compareBtn)compareBtn.addEventListener("click",()=>{
    if(compareSelected.size<1)return;
    compareOpen=true;
    renderCompare();
    $("#compare_panel").scrollIntoView({behavior:"smooth",block:"nearest"});
  });
  if(clearBtn)clearBtn.addEventListener("click",()=>{
    compareSelected.clear();compareOpen=false;render();
  });
})();;
